package com.jaydeep.jobhunter;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import java.net.URI; import java.net.http.*; import java.util.*;
public class RemoteOkCollector implements JobCollector { private static final ObjectMapper M=new ObjectMapper(); private final HttpClient c=HttpClient.newHttpClient(); public String name(){return "RemoteOK";} public List<Job> collect() throws Exception {var r=HttpRequest.newBuilder(URI.create("https://remoteok.com/api")).header("User-Agent","JobHunter/1.0").build();JsonNode a=M.readTree(c.send(r,HttpResponse.BodyHandlers.ofString()).body());List<Job> out=new ArrayList<>();for(JsonNode j:a)if(j.isObject()&&j.has("position"))out.add(new Job(j.path("company").asText(),j.path("position").asText(),j.path("location").asText(),j.path("description").asText()+" "+j.path("tags").toString(),j.path("url").asText(),name()));return out;}}
